template<size_t N>
inline bool matches(const unsigned char* p,const std::array<unsigned char,N>& code,const std::array<unsigned char,N>& mask){
    for(size_t i=0;i<N;++i)if(mask[i]&&p[i]!=code[i])return false;return true;
}
inline bool executable(const unsigned char* p,size_t length,unsigned char* base,size_t size){
    auto at=reinterpret_cast<uintptr_t>(p),begin=reinterpret_cast<uintptr_t>(base);
    if(at<begin||length>size||at-begin>size-length)return false;
    MEMORY_BASIC_INFORMATION m{};
    if(!VirtualQuery(p,&m,sizeof(m))||m.State!=MEM_COMMIT||m.AllocationBase!=base||m.Protect&(PAGE_GUARD|PAGE_NOACCESS))return false;
    if(!(m.Protect&(PAGE_EXECUTE|PAGE_EXECUTE_READ|PAGE_EXECUTE_READWRITE|PAGE_EXECUTE_WRITECOPY)))return false;
    return at+length<=reinterpret_cast<uintptr_t>(m.BaseAddress)+m.RegionSize;
}
inline const unsigned char* relative(const unsigned char* instruction){
    int32_t displacement{};std::memcpy(&displacement,instruction+1,4);
    return reinterpret_cast<const unsigned char*>(reinterpret_cast<uintptr_t>(instruction)+5+static_cast<int64_t>(displacement));
}
inline bool dependencies(const unsigned char* p,unsigned char* base,size_t size){
    // Win64 exception metadata must identify this exact complete function.
    auto nt=reinterpret_cast<IMAGE_NT_HEADERS64*>(base+reinterpret_cast<IMAGE_DOS_HEADER*>(base)->e_lfanew);
    auto directory=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXCEPTION];
    if(directory.VirtualAddress>=size||directory.Size>size-directory.VirtualAddress||directory.Size%sizeof(RUNTIME_FUNCTION))return false;
    auto entries=reinterpret_cast<RUNTIME_FUNCTION*>(base+directory.VirtualAddress);bool boundary=false;
    auto rva=static_cast<DWORD>(p-base);
    size_t low=0,high=directory.Size/sizeof(RUNTIME_FUNCTION);
    while(low<high){auto mid=low+(high-low)/2;auto& entry=entries[mid];if(entry.BeginAddress<rva)low=mid+1;else high=mid;}
    if(low<directory.Size/sizeof(RUNTIME_FUNCTION)){auto& entry=entries[low];boundary=entry.BeginAddress==rva&&entry.EndAddress-entry.BeginAddress==completeCode.size();}
    if(!boundary)return false;
    auto first=relative(p+9),second=relative(p+17),notify=relative(p+37);
    return executable(first,meshesCode.size(),base,size)&&executable(second,clothingCode.size(),base,size)&&executable(notify,notificationCode.size(),base,size)&&
        matches(first,meshesCode,meshesMask)&&matches(second,clothingCode,clothingMask)&&matches(notify,notificationCode,notificationMask);
}
inline void* resolve(std::wstring& error){return NativeContract::resolveCode(completeCode,completeMask,dependencies,error);}
